INSERT INTO cheer (id, member_id, store_id, description, is_admin, created_at) VALUES (1,6,1,'제 인생에 맛집 3곳을 고르라면 그중에 한곳입니다… 금액은 좀 비싸지만 그럼에도 최소 6개월에 한번씩은 방문하는 곳이에요. 6개월에 한번 방문한다고 적다고 생각하실수도 있지만 대구에서 저거 먹으려고 갑니다… 그리고 연신내라서 멀다고 생각하실수도 있지만 가보시면 절대 후회 안하십니다.. 주말에는 웨이팅 필수이고 평일에는 매장 이용하시기에 무리 없으실거에요… 매장은 좀 협소해서 4명이상은 이용 불가능하긴 합니다… 그래도 관심있으시고 회 좋아하시는 분들은 제발 꼭 한번만 드셔보셨으면 좋겠습니다…',0,'2025-08-14 15:00:39'),(2,6,2,'석촌호수쪽에 있는 이자카야 맛집이에요! 항상 석촌호수 근처 방문하면 꼭 여기에서 밥 먹고 2차로 넘어갑니다… 매장이 좀 좁고 사람이 많아서 이용하는데 약간 불편하실 수 있지만 가성비와 맛은 진짜 보장할 수 있어요… 그리고 특히 여기서 먹는 양맥은 최고입니다! 숙성회 시키면 초밥 밥도 같이 나와서 초밥으로 주문하는 것 보다 회로 드시는 걸 더 추천드려요!',0,'2025-08-14 15:03:35'),(3,6,3,'평양 냉면에 도전하신다면 추천드립니다! 우레옥을 먹으셨다면 일반 평양냉면과 우레옥 중간쯤의 맛이에요! 저도 몰랐는데 냉면 주문하실 때 얼음 없이 주문하시면 살얼음 있게 먹을 때보다 훨씬 더 진하게 드실 수 있습니다. 그리고 배가 괜찮으시다면 녹두전도 드시는 걸 추천드려요… 전 처음 먹고 녹두전이 아니라 고기전인줄 알았자나요… 냉면 시키실 때 양 많이 주문하시면 추가 금액 없이 양많이 드실 수 있어요! 여성분 기준에는 양많이 드시면 많을수도 있으니까 참고하시면 좋을 거 같아요!',0,'2025-08-14 15:06:52'),(4,5,4,'여기는 우연히 강남에서 발견한 찐 숨은 맛집인뎅요!! 저는 역삼에서 회사를 다니게 된 후로 너무 지칠땐 .. 여기와서 혼술을 하기도 해요 •• 특유의 분위기와, 손글씨로 적힌 칵테일 메뉴들, 그리고 은은한 위스키향까지 🥹',0,'2025-08-14 15:07:36'),(5,6,5,'햄버거 좋아하시는 분들이라면 강추합니다… 패티를 직접 만드시는데 전혀 짜지 않고 육즙이 가득해서 입에서 그냥 순삭,,, 없어집니다…ㅜ 저는 처음에 베이컨 추가해서 먹었는데 기본도 맛있을거 같아서 다음에는 기본 먹으려구요! 남자친구가 여기서 햄버거 먹고 계속 술먹고 난 다음에 해장을 햄버거로 해요~',0,'2025-08-14 15:07:41'),(6,3,6,'유명해지지마,, 아니 유명해져.. 양가의 감정이 드는 제 이태원 맛집인데요 매운맛이랑 보통맛 반반씩 + 최루탄 주먹밥 시키면 진짜 맛있어서 전쟁 날뻔한거 참았습니다 아 다 먹고 옆에 젤라또 집가서 후식 먹으면 완벽해요',0,'2025-08-14 15:10:11'),(7,6,7,'맛집으로 유명한 곳이에요. 골목식당에서도 소개되었던 곳입니다. 회냉면이 가장 많이 팔리고 가장 인기가 높아요. 물론 다른 메뉴도 최고에요. 극추에요.!!',0,'2025-08-18 17:54:12'),(8,6,8,'신정역 근처에 딱히 맛집이 없는데 이곳저곳 검색하다가 찾게된 집이에요! 간단하게 술 먹고싶은분들도, 여러가지 안주 먹고싶은 분들에게도 딱인 곳입니다. 사이드 메뉴도 다양하게 많아서 한번만 가기에 아쉬운 맛집이에요:)',0,'2025-08-18 17:57:54'),(17,9,17,'여기는 인생 냉면맛집이에요! 다들 와서 드세요',0,'2025-08-22 14:05:07'),(18,10,18,'가게 분위기도 좋고 음식도 맛있고, 가장 좋은 것은 시끄럽지 않다는 것! 추천하는 메뉴는 숙성회~',0,'2025-08-23 03:24:42'),(19,10,19,'완전 음식 그냥 맛있어요! 분위기도 살짝 레트로해서 좋고, 주종도 다양하고, 이야기 나누기도 좋아요~ 음식이 넘사벽입니다.',0,'2025-08-23 03:27:56'),(25,5,19,'분위기가 너무